import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"ADR-0014 — Bases: sottoinsieme supportato, degrado e round-trip","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0014-bases-details.md","filePath":"adr/0014-bases-details.md"}'),n={name:"adr/0014-bases-details.md"};function r(d,e,s,c,l,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0014-—-bases-sottoinsieme-supportato-degrado-e-round-trip" tabindex="-1">ADR-0014 — Bases: sottoinsieme supportato, degrado e round-trip <a class="header-anchor" href="#adr-0014-—-bases-sottoinsieme-supportato-degrado-e-round-trip" aria-label="Permalink to &quot;ADR-0014 — Bases: sottoinsieme supportato, degrado e round-trip&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.2.1, §2.5 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-24</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.2.1 (riga Bases, P1); D-01, D-06; roadmap M6-WP2</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Le Bases sono file <code>.base</code> (YAML) compatibili con Obsidian: filtri, formule e viste (tabella/card) sulle properties indicizzate. Il formato Obsidian non ha una specifica normativa completa: va definito il sottoinsieme che si implementa e come si degrada su ciò che non si capisce, senza mai perdere contenuto dell&#39;utente.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><strong>Motore unico in Go</strong> (<code>internal/bases</code>, dietro <code>BasesAPI</code>); il frontend mostra soltanto il risultato. Parser ed evaluator di espressioni scritti a mano (niente <code>eval</code>), con budget di passi per espressione.</p><p><strong>Supportato.</strong> Radice: <code>filters</code>, <code>formulas</code>, <code>properties.&lt;id&gt;.displayName</code>, <code>views</code>. Filtri: stringa-espressione oppure gruppi <code>and</code>/<code>or</code>/<code>not</code> annidati (<code>not</code> = nessun figlio vero); i filtri di base e di vista si compongono in AND. Viste <code>table</code> e <code>cards</code> con <code>name</code>, <code>filters</code>, <code>order</code>, <code>sort[{property,direction}]</code>, <code>groupBy</code>, <code>limit</code>, <code>summaries</code> (Sum, Average, Min, Max, Median, Range, Count, Empty, Filled, Unique, Earliest, Latest). Riferimenti: <code>file.{name,basename,path,folder,ext,size,ctime,mtime,tags,links}</code>, <code>note.x</code>/<code>x</code>, <code>formula.x</code>, <code>this.x</code>. Tipi: testo, numero, booleano, data, data-ora, lista, link, durata. Espressioni: aritmetica, confronti, <code>&amp;&amp; || !</code>, indici, <code>if</code>, <code>now/today/date/number/link/list/concat/min/max/abs/round/floor/ceil/duration</code>, <code>file.hasTag/inFolder/hasLink/hasProperty</code>, metodi su stringhe (contains, startsWith, endsWith, lower, upper, trim, replace, split, slice, title, repeat), liste (contains, containsAll/Any, join, map, filter con <code>value</code>/<code>index</code> impliciti, sum, count, mean, min, max, unique, sort, flat, reverse, slice, concat), date (campi, <code>format</code> con token moment, <code>+</code>/<code>-</code> durata, <code>date - date</code> = durata con <code>.days</code> ecc., <code>relative</code>). Proprietà mancante ⇒ <code>null</code>; l&#39;aritmetica su <code>null</code> resta <code>null</code>.</p><p><strong>Non supportato (degrado).</strong> Tipi di vista diversi da table/cards: la vista compare nel selettore con avviso &quot;non supportata&quot;, senza righe. Filtro con espressione non valida o struttura sconosciuta: neutro (non nasconde righe), segnalato in <code>Notices</code> e come chip evidenziato. Formula non valida o con errore a runtime: errore solo nella cella (<code>#ERRORE</code>, dettaglio nel tooltip), le altre celle restano. Errore a runtime in un filtro: la riga è esclusa. Opzioni di vista sconosciute (<code>image</code>, <code>cardSize</code>, <code>rowHeight</code>…) sono ignorate. <code>ctime</code> coincide con <code>mtime</code> (non indicizzato). Un YAML non valido mostra l&#39;errore e l&#39;editor YAML grezzo.</p><p><strong>Round-trip.</strong> Una base non si riscrive mai se non su azione esplicita dell&#39;utente (ordinamento, colonne, raggruppamento, filtro semplice, YAML grezzo). Le modifiche operano sull&#39;albero <code>yaml.v3</code> (<code>Node</code>): chiavi sconosciute, commenti, altre viste e stile restano intatti; solo i nodi toccati cambiano e l&#39;indentazione è normalizzata a 2 spazi. I filtri complessi (gruppi, radice non-<code>and</code>) sono chip in sola lettura: aggiungere un filtro a una radice diversa da <code>and</code> la incapsula senza riscriverla; la rimozione è consentita solo per le espressioni semplici dell&#39;<code>and</code> di primo livello. Scrittura atomica con <code>expectedHash</code> (conflitto se il file è cambiato); vault in sola lettura non scrivibili. La modifica inline di una property delega a <code>PropertiesAPI.Update</code> (stesso percorso con hash, schema tipi e commenti preservati); celle formula e colonne <code>file.*</code> sono di sola lettura.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Valutatore anche in TS</strong> — scartata: due implementazioni da tenere allineate; con un solo motore Go non servono fixture di conformità.</li><li><strong>Libreria di espressioni esterna (CEL, expr)</strong> — scartata: sintassi e semantica diverse da Obsidian, superficie d&#39;attacco maggiore.</li><li><strong>Riserializzare l&#39;intero YAML dal modello</strong> — scartata: perde chiavi sconosciute e commenti.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><p>Prestazioni: 10.000 note, filtro + ordinamento ≈ 6,5 ms nel motore e ≈ 86 ms includendo il caricamento da <code>index.db</code> (benchmark <code>BenchmarkRun10kFilterSort</code>, <code>BenchmarkLoadAndRun10k</code>). Il caricamento ricostruisce le note a ogni esecuzione: una cache incrementale è rinviata. Le viste non supportate (mappa, lista) e i formati di colonna avanzati restano per una milestone successiva. Il comportamento fine delle funzioni Obsidian meno comuni può differire: va verificato su vault reali.</p>',13)])])}const g=o(n,[["render",r]]);export{u as __pageData,g as default};
